urlset:
{{- range $p := sort site.Pages "Params.sitemap_loc" }}{{ with $p.Params.sitemap_loc }}

  https://www.ionas.com{{ . }}
  {{ $p.Params.sitemap_priority | default "0.5" }}
  {{ $p.Params.sitemap_changefreq | default "monthly" }}
{{- with $p.Params.sitemap_lastmod }}
  {{ . }}
{{- end }}

{{- end }}{{ end }}
{{- range hugo.Data.sitemap_extra.urls }}

  https://www.ionas.com{{ .loc }}
  {{ .priority }}
  {{ .changefreq }}
{{- with .lastmod }}
  {{ . }}
{{- end }}

{{- end }}
